tape( 'if provided an `N` less than or equal to `0`, the function returns the output array unchanged', function test( t ) {
	var expected;
	var out;

	out = [ 0.0, 0.0, 0.0, 0.0 ];

	ghadamard( 0, out, 0, 1, 0 );

	expected = [ 0.0, 0.0, 0.0, 0.0 ];

	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

